-	if (fm->ret_size > sizeof(u32))
-		end_addr -= 3;
-
-	/* mov dword ptr [ebp+off],eax */
-	if (fm->ret_size)
+	switch (fm->ret_size) {
+	case 0:
+		break;
+	case sizeof(u8):
+	case sizeof(u16):
+		/* mov[s|z]x eax,[a]x */
 		end_addr -= 3;
+		fallthrough;
+	case sizeof(u32):
+		/* cdq or xor edx,edx */
+		end_addr -= fm->ret_flags & BTF_FMODEL_SIGNED_ARG ? 1 : 2;
+		fallthrough;
+	case sizeof(u64):
+		/* Store EDX:EAX in R0. */
+		end_addr -= 6;
+		break;
+	default:
+		return -EINVAL;
+	}
 
 	jmp_offset = (u8 *)__bpf_call_base + insn->imm - end_addr;
 	if (!is_simm32(jmp_offset)) {
@@ -1637,15 +1649,38 @@ static int emit_kfunc_call(const struct bpf_prog *bpf_prog, u8 *end_addr,
 
 	EMIT1_off32(0xE8, jmp_offset);
 
-	if (fm->ret_size)
+	switch (fm->ret_size) {
+	case sizeof(u8):
+		/* mov[s|z]x eax,al */
+		EMIT3(0x0F, fm->ret_flags & BTF_FMODEL_SIGNED_ARG ? 0xBE : 0xB6,
+		      add_2reg(0xC0, IA32_EAX, IA32_EAX));
