+		EMIT3(0x0F, fm->ret_flags & BTF_FMODEL_SIGNED_ARG ? 0xBF : 0xB7,
+		      add_2reg(0xC0, IA32_EAX, IA32_EAX));
+		break;
+	default:
+		break;
+	}
+
+	if (fm->ret_size && fm->ret_size <= sizeof(u32)) {
+		if (fm->ret_flags & BTF_FMODEL_SIGNED_ARG)
+			/* cdq */
+			EMIT1(0x99);
+		else
